mapper.select:
SELECT dr.*, COALESCE(d.building, dr.building, CONVERT(ud.building USING utf8mb4) COLLATE utf8mb4_unicode_ci) AS building, COALESCE(d.room_no, dr.room_no, CONVERT(ud.room USING utf8mb4) COLLATE utf8mb4_unicode_ci) AS room_no, u.username, u.real_name, u.phone, hu.real_name AS handler_name FROM dormitory_repair dr LEFT JOIN dormitory d ON dr.dormitory_id = d.id LEFT JOIN user_dormitory ud ON dr.user_id = ud.user_id INNER JOIN user u ON dr.user_id = u.user_id LEFT JOIN user hu ON dr.handler_id = hu.user_id
AND dr.status = #{status}
AND COALESCE(d.building, dr.building, CONVERT(ud.building USING utf8mb4) COLLATE utf8mb4_unicode_ci) = #{building}
AND dr.urgency = #{urgency}
ORDER BY CASE dr.urgency WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END, dr.create_time ASC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM dormitory_repair dr
LEFT JOIN dormitory d ON dr.dormitory_id = d.id
LEFT JOIN user_dormitory ud ON dr.user_id = ud.user_id


        AND dr.status = #{status}


        AND COALESCE(d.building, dr.building, CONVERT(ud.building USING utf8mb4) COLLATE utf8mb4_unicode_ci) = #{building}


        AND dr.urgency = #{urgency}

SELECT dr.status, COUNT(*) AS cnt FROM dormitory_repair dr LEFT JOIN dormitory d ON dr.dormitory_id = d.id LEFT JOIN user_dormitory ud ON dr.user_id = ud.user_id
AND COALESCE(d.building, dr.building, CONVERT(ud.building USING utf8mb4) COLLATE utf8mb4_unicode_ci) = #{building}
GROUP BY dr.status

mapper.update:
UPDATE dormitory_repair
SET status = 'CANCELLED',
    update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = #{currentStatus}

